package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.View;
import androidx.test.platform.app.InstrumentationRegistry;
import androidx.test.uiautomator.*;
import java.io.File;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;

/** Configuration/private SQLite only. Never launches the alarm, sensors, pinning or an output. */
public class ChallengeRoutineFlowTest {
    private final Instrumentation i=InstrumentationRegistry.getInstrumentation();private final Context c=i.getTargetContext();private final UiDevice device=UiDevice.getInstance(i);private AlarmEditorActivity activity;
    private UiObject2 object(String desc)throws Exception{UiObject2 found=device.wait(Until.findObject(By.desc(desc)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue("Scrollable route for "+desc,scroll.exists());scroll.scrollIntoView(new UiSelector().description(desc));found=device.wait(Until.findObject(By.desc(desc)),3000);}assertNotNull(desc,found);return found;}
    private void click(String text)throws Exception{UiObject2 found=device.wait(Until.findObject(By.text(text)),2000);if(found==null){UiScrollable scroll=new UiScrollable(new UiSelector().scrollable(true));assertTrue(scroll.exists());scroll.scrollIntoView(new UiSelector().text(text));found=device.wait(Until.findObject(By.text(text)),3000);}assertNotNull(text,found);found.click();device.waitForIdle();}
    private void pick(String setting,String value)throws Exception{object(setting).click();assertTrue(device.wait(Until.hasObject(By.desc("Options for "+setting)),4000));object(value).click();assertTrue(device.wait(Until.gone(By.desc("Options for "+setting)),4000));device.waitForIdle();}
    private void launch(Alarm alarm)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{c.startActivity(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",alarm.json().toString()).putExtra("visualReview",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text("Edit alarm")),5000));}
    private void recreate(String title)throws Exception{Instrumentation.ActivityMonitor monitor=i.addMonitor(AlarmEditorActivity.class.getName(),null,false);try{i.runOnMainSync(activity::recreate);activity=(AlarmEditorActivity)monitor.waitForActivityWithTimeout(5000);assertNotNull(activity);}finally{i.removeMonitor(monitor);}assertTrue(device.wait(Until.hasObject(By.text(title)),5000));}
    private void capture(String suffix)throws Exception{CountDownLatch frame=new CountDownLatch(1);long until=SystemClock.elapsedRealtime()+5000;boolean[] registered={false};while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{if(activity!=null&&!activity.isDestroyed()&&activity.hasWindowFocus()){View decor=activity.getWindow().getDecorView();if(decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused configuration window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"routine-"+suffix+".png")));}
    @Test public void orderedTasksConfigureReorderCancelRecreateAndPersistWithoutOutputs()throws Exception{
        assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",device.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        String name="routine-"+UUID.randomUUID()+".db";Map<String,?> originalPrefs=new HashMap<>(Prefs.of(c).getAll());Records.Factory previousRecords=Records.factory;AlarmScheduling.Port previousScheduling=AlarmScheduling.port;int[] scheduled={0};List<Activity> owned=new CopyOnWriteArrayList<>();Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){owned.add(a);assertTrue("Configuration only",a instanceof AlarmEditorActivity);}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);
        try{
            i.runOnMainSync(()->{Records.factory=context->new Store(context,name);AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse(alarm.enabled);scheduled[0]++;}};});
            Alarm legacy=new Alarm(1);legacy.label="Routine fixture";legacy.difficulty=3;Alarm other=new Alarm(2);other.label="Preserved second alarm";String untouched=other.json().toString();try(Store store=new Store(c,name)){store.save(legacy);store.save(other);}assertFalse(legacy.json().has("routine"));launch(legacy);click("Challenges");assertNotNull(object("Edit task 1 Math"));capture("legacy");
            object("Challenge routine options").click();assertNotNull(object("Routine mode"));recreate("Routine settings");click("Done");assertNotNull(object("Edit task 1 Math"));
            object("Edit task 1 Math").click();pick("Rounds","2 rounds");click("Use Math");click("More task types");assertNotNull(object("Configure Math"));object("Configure Memory").click();recreate("Use Memory");object("Back").click();assertTrue(device.wait(Until.hasObject(By.text("More task types")),4000));object("Configure Memory").click();pick("Rounds","1 round");click("Use Memory");object("Configure Retype").click();pick("Rounds","2 rounds");click("Use Retype");assertNotNull(object("Edit task 3 Retype"));capture("ordered");
            android.graphics.Rect handle=object("Order or remove task 3").getVisibleBounds(),cancelTarget=device.findObject(By.text("Challenges")).getVisibleBounds();assertTrue(device.drag(handle.centerX(),handle.centerY(),cancelTarget.centerX(),cancelTarget.centerY(),30));device.waitForIdle();assertNotNull(object("Edit task 1 Math"));assertNotNull(object("Edit task 3 Retype"));
            handle=object("Order or remove task 3").getVisibleBounds();android.graphics.Rect first=object("Edit task 1 Math").getVisibleBounds();assertTrue(device.drag(handle.centerX(),handle.centerY(),first.centerX(),first.centerY(),30));device.waitForIdle();assertNotNull("Actual long-press drag moves the draft",object("Edit task 1 Retype"));assertNotNull(object("Edit task 2 Math"));assertNotNull(object("Edit task 3 Memory"));try(Store store=new Store(c,name)){assertFalse("Drag does not write before Save alarm",store.alarm(1).json().has("routine"));assertEquals(untouched,store.alarm(2).json().toString());}
            object("Order or remove task 1").click();object("Move down").click();assertNotNull(object("Edit task 2 Retype"));assertNotNull(object("Edit task 3 Memory"));capture("reordered");object("Edit task 2 Retype").click();pick("Rounds","3 rounds");recreate("Use Retype");capture("recreated");object("Back").click();object("Edit task 2 Retype").click();object("Rounds").click();assertTrue("Cancelled step edit preserves two rounds",object("2 rounds").isChecked());click("Cancel");pick("Rounds","3 rounds");click("Use Retype");
            object("Order or remove task 3").click();object("Remove task").click();assertFalse(device.hasObject(By.desc("Edit task 3 Memory")));capture("removed");click("Save routine");assertNotNull(device.findObject(By.text("2 tasks")));try(Store store=new Store(c,name)){assertFalse("Only Save alarm writes",store.alarm(1).json().has("routine"));assertEquals(untouched,store.alarm(2).json().toString());}assertEquals(0,scheduled[0]);click("Save alarm");long until=SystemClock.elapsedRealtime()+5000;while(!activity.isDestroyed()&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(activity.isDestroyed());
            Alarm saved;try(Store store=new Store(c,name)){saved=store.alarm(1);assertEquals(untouched,store.alarm(2).json().toString());assertEquals(2,saved.challenges().tasks.size());assertEquals("Math",saved.challenges().tasks.get(0).type);assertEquals(2,saved.challenges().tasks.get(0).rounds);assertEquals("Retype",saved.challenges().tasks.get(1).type);assertEquals(3,saved.challenges().tasks.get(1).rounds);assertEquals(5,saved.challenges().units());assertEquals(saved.json().toString(),Alarm.read(new JSONObject(saved.json().toString())).json().toString());Backup.validate(store.backup());}
            assertEquals(1,scheduled[0]);launch(saved);click("Challenges");assertNotNull(object("Edit task 2 Retype"));capture("reopened");object("Configure Shake").click();pick("Shakes","20 shakes");click("Use Shake");assertNotNull(object("Edit task 3 Shake"));object("Back").click();click("Save alarm");try(Store store=new Store(c,name)){assertEquals("Cancelling routine discards added Shake",2,store.alarm(1).challenges().tasks.size());assertEquals(untouched,store.alarm(2).json().toString());}
            JSONObject invalid=saved.json();invalid.put("routine",new JSONArray().put(new JSONObject().put("type","Walk").put("rounds",1)));assertTrue(Alarm.read(invalid).routineInvalid);assertEquals("Walk",Alarm.read(invalid).json().getJSONArray("routine").getJSONObject(0).getString("type"));try(Store store=new Store(c,name)){JSONObject backup=store.backup();backup.put("alarms",new JSONArray().put(invalid).put(other.json()));assertThrows(JSONException.class,()->Backup.validate(backup));String beforeInvalid=store.backup().toString();List<JSONArray> malformed=new ArrayList<>();malformed.add(new JSONArray());malformed.add(invalid.getJSONArray("routine"));malformed.add(new JSONArray().put(new JSONObject().put("type","Math").put("rounds",1.5)));malformed.add(new JSONArray().put(new JSONObject().put("type","Math").put("rounds","2")));malformed.add(new JSONArray().put(new JSONObject().put("type",7).put("rounds",2)));JSONArray oversized=new JSONArray();for(int n=0;n<9;n++)oversized.put(new JSONObject().put("type","Math").put("rounds",1));malformed.add(oversized);for(JSONArray bad:malformed){JSONObject rejected=saved.json().put("routine",bad);Alarm retained=Alarm.read(rejected);assertTrue(retained.routineInvalid);assertEquals(bad.toString(),retained.json().getJSONArray("routine").toString());JSONObject badBackup=store.backup().put("alarms",new JSONArray().put(rejected).put(other.json()));assertThrows("Bad routines must fail before replacing private data",JSONException.class,()->Backup.restoreData(store,badBackup));assertEquals(beforeInvalid,store.backup().toString());}}assertEquals(originalPrefs,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));
        }catch(Exception|AssertionError failure){try{File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());device.takeScreenshot(new File(folder,"routine-failure.png"));device.dumpWindowHierarchy(new File(folder,"routine-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed())a.finish();});i.waitForIdleSync();long until=SystemClock.elapsedRealtime()+5000;while(owned.stream().anyMatch(a->!a.isDestroyed())&&SystemClock.elapsedRealtime()<until)SystemClock.sleep(50);assertTrue(owned.stream().allMatch(Activity::isDestroyed));}finally{app.unregisterActivityLifecycleCallbacks(callbacks);i.runOnMainSync(()->{Records.factory=previousRecords;AlarmScheduling.port=previousScheduling;});if(owned.stream().allMatch(Activity::isDestroyed))c.deleteDatabase(name);}}
    }
}
